package hu.boltseged.account;
import org.junit.jupiter.api.Test; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import java.math.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AccountProfileControllerTest {@Test void customerProfileUpdatePreservesEmailPricingRoleAndActive(){Account account=new Account(null,"customer@example.com","hash","CUSTOMER");account.update(null,null,null,null,"customer@example.com","FIXED",new BigDecimal("1000"));account.setActive(false);AccountRepository repo=mock(AccountRepository.class);when(repo.save(account)).thenReturn(account);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(account,null));new AccountProfileController(repo).update(new AccountProfileController.ProfileRequest("Company","Tax","Address","Contact"));assertEquals("Company",account.getCompanyName());assertEquals("customer@example.com",account.getEmail());assertEquals("FIXED",account.getPricingType());assertEquals(new BigDecimal("1000"),account.getPricingValue());assertEquals("CUSTOMER",account.getRole());assertFalse(account.isActive());}}
